suppressPackageStartupMessages(library(edgeR));suppressPackageStartupMessages(library(limma))
B<-'/mnt/BioDisk/wangmingyuan/GI_preanalysis_20260923';V<-file.path(B,'GC_validation_v2');O<-file.path(V,'candidate_discovery')
writeLines(c('Post-hoc anatomical sensitivity motivated by candidate localization, not prespecified primary discovery.', 'Two whole-genome models: endothelial+mesothelial proxies, and adipocyte+myeloid+endothelial+mesothelial proxies.', 'All model outcomes retained. Proxies are not true proportions; correlated and tumor-expressed marker effects cannot establish cell-intrinsic change.'),file.path(O,'ANATOMY_PLAN.txt'))
m<-read.delim(file.path(V,'04_results/FABP4_audit/sample_values.tsv'),check.names=FALSE);m$patient<-factor(m$patient);m$site<-factor(m$site,levels=c('GCPT','GCPM'));m$preservation<-factor(m$preservation)
lc<-read.delim(gzfile(file.path(B,'03_processed/GC314812_TMM_logCPM.tsv.gz')),check.names=FALSE);E<-as.matrix(lc[,m$sample]);gs<-list(endothelial=c('PECAM1','VWF','CLDN5','KDR'),mesothelial=c('UPK3B','CALB2','MSLN','WT1'))
for(g in names(gs)){measured<-gs[[g]][gs[[g]]%in%lc$symbol];cat(g,'measured',paste(measured,collapse=','),'missing',paste(setdiff(gs[[g]],measured),collapse=','),'\n');stopifnot(length(measured)>=3);m[[g]]<-colMeans(E[lc$symbol%in%gs[[g]],,drop=FALSE])}
x<-read.delim(gzfile(file.path(B,'02_raw/GSE314812_counts.tsv.gz')),check.names=FALSE);cnt<-as.matrix(x[,m$sample]);rownames(cnt)<-x$gene_id
orig<-read.delim(file.path(B,'04_results/GC_bulk/paired_preservation_adjusted_DE.tsv'),check.names=FALSE);d<-calcNormFactors(DGEList(cnt[match(orig$gene_id,rownames(cnt)),,drop=FALSE]))
forms<-list(anatomy=~patient+preservation+endothelial+mesothelial+site,four_proxies=~patient+preservation+adipocyte+myeloid+endothelial+mesothelial+site)
sel<-read.delim(file.path(O,'screen_pass_all.tsv'));sel<-sel$gene_id[sel$n_supported_models>=3&sel$symbol!='FABP4'];out<-list()
for(k in names(forms)){de<-model.matrix(forms[[k]],m);stopifnot(qr(de)$rank==ncol(de));v<-voom(d,de,plot=FALSE);fit<-eBayes(lmFit(v,de));tt<-topTable(fit,coef='siteGCPM',number=Inf,sort.by='none',confint=TRUE);tt$gene_id<-rownames(tt);tt$symbol<-orig$symbol[match(tt$gene_id,orig$gene_id)];write.table(tt,gzfile(file.path(O,paste0(k,'_all_genes.tsv.gz'))),sep='\t',quote=FALSE,row.names=FALSE);out[[k]]<-data.frame(model=k,tt[tt$gene_id%in%sel,],residual_df=nrow(de)-ncol(de))}
y<-do.call(rbind,out);write.table(y,file.path(O,'candidate_anatomy_sensitivity.tsv'),sep='\t',quote=FALSE,row.names=FALSE);write.table(m,file.path(O,'anatomy_proxy_sample_scores.tsv'),sep='\t',quote=FALSE,row.names=FALSE);print(y[y$symbol%in%c('TMEM91','COPZ2','CDH23','CPTP','RAP1GAP2','OPLAH','IGSF10'),c('model','symbol','logFC','P.Value','adj.P.Val','residual_df')]);writeLines('exit_code=0; full_rank_models; full_genome_tables_saved',file.path(O,'ANATOMY_COMPLETE.txt'))

